// Prepare structured author and catalog data for AI grounding
const body = $json.body || $json;

const author = body.author || body;
const summary = body.summary || body;
const books = body.books || [];

// Format books cleanly if present
let booksFormatted = '';
if (Array.isArray(books) && books.length > 0) {
  booksFormatted = books.map((b, i) => {
    const isProd = (b.status || '').includes('Production');
    if (isProd) {
      return `${i+1}. "${b.title}" (Status: ${b.status}, ISBN: Pending Assignment, Copies Sold: 0, Pending: ₹0)`;
    }
    return `${i+1}. "${b.title}" (Status: ${b.status}, ISBN: ${b.isbn || 'N/A'}, Copies Sold: ${b.total_copies_sold || 0}, Lifetime Earned: ₹${b.total_royalty_earned || 0}, Paid: ₹${b.royalty_paid || 0}, Pending Balance: ₹${b.royalty_pending || 0})`;
  }).join('\n');
} else {
  booksFormatted = 'Registered catalog titles under official BookLeaf publishing contract.';
}

const pendingAmount = Number(summary.total_pending || summary.cached_total_pending || 0);
let thresholdNote = '';
if (pendingAmount >= 1000) {
  thresholdNote = 'Meets the ₹1,000 threshold and is scheduled for the upcoming quarterly payout cycle (within 45 days post-quarter close).';
} else if (pendingAmount > 0) {
  thresholdNote = 'Under the ₹1,000 threshold and will automatically roll over to the subsequent quarter without administrative fees.';
} else {
  thresholdNote = 'All historical royalties have been fully settled to your account.';
}

return [{
  json: {
    author_name: author.name || 'Author',
    author_email: author.email || '',
    author_city: author.city || '',
    total_earned: summary.total_earned || summary.cached_total_earned || 0,
    total_paid: summary.total_paid || summary.cached_total_paid || 0,
    total_pending: pendingAmount,
    threshold_explanation: thresholdNote,
    books_formatted_list: booksFormatted
  }
}];
